// samplesDir is generated by Phase 1A's sample harness. Derived from
// this test file's location so it works on any checkout path (CI
// workspaces are not /home/daal).
var samplesDir = filepath.Join(testRepoRoot(), "specs", "test-vectors", "bundles", "samples")

func testRepoRoot() string {
	_, file, _, _ := runtime.Caller(0)
	// .../core/trust/importer_test.go → repo root.
	return filepath.Clean(filepath.Join(filepath.Dir(file), "..", ".."))
}

func openStore(t *testing.T) *routestore.Store {
	t.Helper()
	s, err := routestore.Open(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { s.Close() })
	return s
}

func wordlists() bundle.Wordlists { return publisher.DefaultWordlists() }

func TestImportSignedASample_TOFUFlow(t *testing.T) {
	s := openStore(t)
	a := &trust.StoreAdapter{S: s}
	now := time.Now().UTC()

	// First import → trust prompt expected.
	body := mustReadFile(t, filepath.Join(samplesDir, "signed-A.sbp"))
	v, err := importer.ImportBytes(body, a, wordlists(), now)
	if err != nil {
		t.Fatalf("first import error: %v (verdict %+v)", err, v)
	}
	if v.Kind != importer.VerdictTrustPromptNeeded {
		t.Fatalf("expected trust prompt, got %v reason=%q", v.Kind, v.Reason)
	}
	if v.RouteCount != 1 || v.HexEN == "" || v.HexFA == "" {
		t.Fatalf("unexpected verdict: %+v", v)
	}

	// User trusts the publisher → silent import on the second call.
	v2, err := importer.AcceptTrustPrompt("trust", body, a, wordlists(), now)
	if err != nil || v2.Kind != importer.VerdictImported {
		t.Fatalf("accept-trust failed: kind=%v err=%v", v2.Kind, err)
	}
	routes, err := s.ListRoutes()
	if err != nil || len(routes) != 1 {
		t.Fatalf("routes after import: %v %v", routes, err)
	}
	if routes[0].TrustState != "tofu" {
		t.Fatalf("trust_state %q, want tofu", routes[0].TrustState)
	}
	if got, err := s.GetSecret("route:" + routes[0].RouteID); err != nil || len(got) == 0 {
		t.Fatalf("profile secret missing: %v", err)
	}

	// Re-importing the same bundle is silent (already pinned).
	v3, err := importer.ImportBytes(body, a, wordlists(), now)
	if err != nil || v3.Kind != importer.VerdictImported {
		t.Fatalf("re-import expected silent: kind=%v err=%v", v3.Kind, err)
	}
}

